// Checks the non-lesson content against the model items (Phase D). No browser needed.
// Usage:  bun tools/content-check.js                (all types: the progress report)
//         bun tools/content-check.js lab case       (only some types)
//         bun tools/content-check.js -v             (also show warnings)
//         bun tools/content-check.js --save-ids     (rewrite tools/content-ids.json, owner only)
// Types: playground, lab, case, challenge, project, solution, scenario.
// Exit code 1 if any checked item fails. Do not edit this file to make an item pass.
const fs = require('fs'), path = require('path'), vm = require('vm');
const root = path.join(__dirname, '..');
const args = process.argv.slice(2);
const verbose = args.includes('-v');
const saveIds = args.includes('--save-ids');
const only = args.filter(a => !a.startsWith('-'));

/* ---------- load the content files with a small fake SDA ---------- */
const stub = new Proxy(function () {}, {
  get: (t, k) => (k === Symbol.toPrimitive ? () => '' : k === 'then' ? undefined : stub),
  apply: () => stub, construct: () => stub, set: () => true,
});
const soft = obj => new Proxy(obj, { get: (t, k) => (k in t ? t[k] : stub), set: (t, k, v) => ((t[k] = v), true) });
const TYPES = ['playground', 'lab', 'case', 'challenge', 'project', 'solution', 'scenario'];
const FILES = {
  playground: ['js/playgrounds'], lab: ['js/labs/labs.js'], case: ['js/cases'],
  challenge: ['js/pages/practice.js', 'js/pages/practice-b.js'],
  project: ['js/pages/projects.js', 'js/pages/projects-b.js', 'js/pages/projects-c.js'],
  solution: ['js/pages/interview-solutions-a.js', 'js/pages/interview-solutions-b.js', 'js/pages/interview-solutions-c.js'],
  scenario: ['js/pages/principal-b.js'],
};
const items = Object.fromEntries(TYPES.map(t => [t, []]));
const loadErrors = [];
function loadFile(file, rel) {
  const SDA = soft({ register: d => { if (d && items[d.kind]) items[d.kind].push(Object.assign({}, d, { file: rel })); } });
  const win = soft({ SDA });
  const doc = soft({});
  const origError = console.error; console.error = () => {};
  try { new Function('window', 'document', 'SDA', fs.readFileSync(file, 'utf8'))(win, doc, SDA); }
  catch (e) { loadErrors.push(`${rel}: ${e.message}`); }
  console.error = origError;
}
for (const t of TYPES) {
  for (const f of FILES[t]) {
    const p = path.join(root, f);
    if (fs.statSync(p).isDirectory()) fs.readdirSync(p).filter(x => x.endsWith('.js') && x !== 'engine.js').sort().forEach(x => loadFile(path.join(p, x), `${f}/${x}`));
    else loadFile(p, f);
  }
}

/* ---------- text helpers ---------- */
const decode = s => s.replace(/&nbsp;/g, ' ').replace(/&amp;/g, '&').replace(/&[a-z]+;|&#\d+;/gi, ' ');
const prose = s => decode(String(s || '').replace(/<pre[\s\S]*?<\/pre>|<code[\s\S]*?<\/code>/g, ' ').replace(/<[^>]+>/g, ' '));
const sentences = s => decode(String(s || '').replace(/<pre[\s\S]*?<\/pre>|<code[\s\S]*?<\/code>/g, ' ').replace(/<\/?(li|td|th|h\d|p|tr|ul|ol|div|table)\b[^>]*>/gi, '\n').replace(/<[^>]+>/g, ' '))
  .split(/(?<=[.!?])\s+|\n/).map(x => x.trim()).filter(x => /[a-z]/i.test(x));
const nWords = s => prose(s).split(/\s+/).filter(Boolean).length;
const nSent = s => sentences(s).length;
const count = (s, re) => (String(s || '').match(re) || []).length;
function strings(v, where, out) {
  if (typeof v === 'string') out.push([where, v]);
  else if (Array.isArray(v)) v.forEach((x, i) => strings(x, `${where}[${i}]`, out));
  else if (v && typeof v === 'object') for (const k in v) if (k !== 'file') strings(v[k], where ? `${where}.${k}` : k, out);
  return out;
}
const get = (o, p) => p.split('.').reduce((a, k) => (a == null ? a : a[k]), o);

/* ---------- checks every type shares ---------- */
function common(it, codeKeys, F, W) {
  const all = strings(it, '', []).filter(([w]) => !codeKeys.some(k => w === k || w.startsWith(k + '.') || w.endsWith(k)));
  const em = all.filter(([, s]) => s.includes('—')).map(([w]) => w);
  if (em.length) F.push(`em dash (—) in ${em.slice(0, 4).join(', ')}${em.length > 4 ? ' …' : ''}`);
  const noCode = s => String(s).replace(/<pre[\s\S]*?<\/pre>|<code[\s\S]*?<\/code>/g, ' ');
  const links = all.filter(([, s]) => /<a\s[^>]*href|https?:\/\//i.test(noCode(s))).map(([w]) => w);
  if (links.length) F.push(`link in ${links.slice(0, 4).join(', ')}`);
  const semis = all.reduce((n, [, s]) => n + count(prose(s), /;/g), 0);
  if (semis > 2) F.push(`${semis} semicolons (max 2)`);
  all.forEach(([w, s]) => sentences(s).filter(x => x.split(/\s+/).length > 28).forEach(x => W.push(`long sentence in ${w}: "${x.slice(0, 50)}…"`)));
}
/* node ids used by diagrams, flows and failures must exist */
function miniGraph(dg, label, F) {
  if (!dg || !Array.isArray(dg.n)) { F.push(`${label}: diagram missing`); return; }
  const ids = new Set(dg.n.map(n => n[0]));
  String(dg.e || '').trim().split(/\s+/).filter(Boolean).forEach(x => { const [a, b] = x.split('~')[0].split('>'); if (!ids.has(a) || !ids.has(b)) F.push(`${label}: edge ${x} uses an unknown node`); });
  (dg.f || []).forEach(([, hops]) => String(hops).split('|').forEach(x => {
    const ab = x.indexOf(':') >= 0 ? x.slice(0, x.indexOf(':')) : x; const [a, b] = ab.split('>');
    if (!ids.has((a || '').trim()) || !ids.has((b || '').trim())) F.push(`${label}: animated step "${x.slice(0, 30)}" uses an unknown node`);
  }));
}
function caseGraph(c, F) {
  const A = c.arch || {}; const ids = new Set((A.nodes || []).map(n => n.id)); const bad = new Set();
  const chk = (i, w) => { if (i != null && !ids.has(i)) bad.add(`${w}:${i}`); };
  (A.edges || []).forEach(e => { chk(e.from, 'edge'); chk(e.to, 'edge'); });
  (c.evolution || []).forEach((e, k) => { (e.hot || []).forEach(i => chk(i, `evolution ${k}`)); (e.down || []).forEach(i => chk(i, `evolution ${k}`)); Object.keys(e.sub || {}).forEach(i => chk(i, `evolution ${k}`)); (e.flow || []).forEach(f => { chk(f[0], `evolution ${k}`); chk(f[1], `evolution ${k}`); }); });
  (c.flows || []).forEach(fl => (fl.steps || []).forEach(s => (s.flow || []).forEach(f => { chk(f[0], 'flows'); chk(f[1], 'flows'); })));
  (c.breakIt || []).forEach(b => { (b.kill || []).forEach(i => chk(i, 'breakIt')); (b.hot || []).forEach(i => chk(i, 'breakIt')); (b.flow || []).forEach(f => { chk(f[0], 'breakIt'); chk(f[1], 'breakIt'); }); });
  if (bad.size) F.push(`unknown diagram node ids: ${[...bad].slice(0, 5).join(', ')}`);
}
const summaryRules = (s, F, max = 2) => {
  if (!s) F.push('summary missing');
  else { if (nSent(s) > max) F.push(`summary has ${nSent(s)} sentences (max ${max})`); if (nWords(s) > 45) F.push(`summary is ${nWords(s)} words (max 45)`); }
};

/* ---------- one checker per type ---------- */
const CHECK = {
  playground(p, F, W) {
    summaryRules(p.summary, F);
    const x = p.explain || '';
    if (!/<h3>\s*How to use it\s*<\/h3>/i.test(x)) F.push('explain has no <h3>How to use it</h3>');
    else { const n = count(x.split(/<h3>\s*What to notice/i)[0], /<li>/g); if (n < 2 || n > 4) F.push(`"How to use it" has ${n} steps (need 2 to 4)`); if (!/<ol>/.test(x)) F.push('"How to use it" must be a numbered list (<ol>)'); }
    if (!/<h3>\s*What to notice\s*<\/h3>/i.test(x)) F.push('explain has no <h3>What to notice</h3>');
    else { const n = count(x.split(/<h3>\s*What to notice/i)[1].split(/<div class="callout/)[0], /<li>/g); if (n < 1 || n > 3) F.push(`"What to notice" has ${n} bullets (need 1 to 3)`); }
    if (!/Important point/i.test(x)) F.push('explain has no "Important point" box');
    if (nWords(x) > 190) F.push(`explain is ${nWords(x)} words (max 190)`);
    if (!p.mount) F.push('mount missing');
    common(p, [], F, W);
  },
  lab(l, F, W) {
    summaryRules(l.summary, F);
    const x = l.explain || '';
    if (!/<h3>\s*What you will build\s*<\/h3>/i.test(x)) F.push('explain has no <h3>What you will build</h3>');
    if (!/<h3>\s*How it works\s*<\/h3>/i.test(x)) F.push('explain has no <h3>How it works</h3>');
    else { const n = count(x.split(/<h3>\s*How it works/i)[1].split(/<h3>/)[0], /<li>/g); if (n < 3 || n > 5) F.push(`"How it works" has ${n} steps (need 3 to 5)`); }
    if (!/<h3>\s*What to notice\s*<\/h3>/i.test(x)) F.push('explain has no <h3>What to notice</h3>');
    if (!/Important point/i.test(x)) F.push('explain has no "Important point" box');
    if (!/Part 1/.test(l.challenge || '') || !/Part 2/.test(l.challenge || '')) F.push('challenge needs "Part 1" and "Part 2"');
    if (nWords(x) > 190) F.push(`explain is ${nWords(x)} words (max 190)`);
    // the code must run and every check() must pass
    const out = []; let checks = 0, failed = 0;
    const ctx = { console: { log: (...a) => out.push(a.join(' ')), warn() {}, error() {} }, check: (n, c) => { checks++; if (!c) { failed++; out.push('FAILED: ' + n); } }, performance: { now: () => Date.now() }, setTimeout, clearTimeout };
    try { vm.runInNewContext(String(l.code || '').replace(/^\n/, ''), ctx, { timeout: Math.min(l.timeout || 4000, 10000) }); }
    catch (e) { F.push(`code does not run: ${String(e.message).split('\n')[0]}`); }
    if (!checks) F.push('code has no check() calls');
    if (failed) F.push(`${failed} of ${checks} check() calls fail`);
    common(l, ['code'], F, W);
  },
  case(c, F, W) {
    summaryRules(c.summary, F);
    if (!/A small example/i.test(get(c, 'overview.what') || '')) F.push('overview.what does not open with a small example');
    const E = c.evolution || [];
    if (E.length < 5) F.push(`evolution has ${E.length} steps (need 5 or more)`);
    E.forEach((e, k) => { ['breaks', 'fix'].forEach(f => { if (k === 0 && f === 'breaks') return; const n = count(e[f], /<p>/g); if (n > 2) F.push(`evolution ${k} "${f}" has ${n} paragraphs (max 2)`); }); });
    (c.scale || []).forEach((r, i) => { if (!r.math || !/\d/.test(r.math)) F.push(`scale row ${i} (${r.k}) shows no math`); });
    if ((c.twists || []).length < 4) F.push(`${(c.twists || []).length} interview twists (need 4 or more)`);
    caseGraph(c, F);
    common(c, ['dataModel.code', 'lab.pseudocode.code', '.req', '.res'], F, W);
  },
  challenge(c, F, W) {
    if ((c.hints || []).length !== 3) F.push(`${(c.hints || []).length} hints (need exactly 3)`);
    else if (!/\?/.test(c.hints[0])) F.push('hint 1 should be a question');
    const s = c.solution || {};
    if (!s.summary) F.push('solution.summary missing'); else if (nSent(s.summary) > 3) F.push(`solution summary has ${nSent(s.summary)} sentences (max 3)`);
    (s.points || []).forEach(([hd, body]) => String(body).split(/<\/p>/).forEach(p => { if (nSent(p) > 3) F.push(`point "${hd}" has a paragraph of ${nSent(p)} sentences (max 3)`); }));
    if ((c.constraints || []).length > 6) F.push(`${c.constraints.length} constraints (max 6)`);
    (c.constraints || []).forEach(x => { if (nWords(x) > 25) F.push(`constraint is ${nWords(x)} words (max 25): "${prose(x).slice(0, 40)}…"`); });
    if (s.diagram) miniGraph(s.diagram, 'solution diagram', F);
    common(c, [], F, W);
  },
  project(p, F, W) {
    const FIELDS = ['req', 'fr', 'nfr', 'est', 'entities', 'apis', 'hld', 'components', 'tech', 'tradeoffs', 'v1', 'bottlenecks', 'scaling', 'improvements', 'failures', 'observability', 'review'];
    FIELDS.forEach(k => { if (p[k] == null || (Array.isArray(p[k]) && !p[k].length)) F.push(`stage "${k}" is missing`); });
    if (!/A small example/i.test(p.req || '')) F.push('requirement does not open with a small example');
    (p.est || []).forEach((r, i) => { if (!r[2] || !String(r[2]).trim()) F.push(`estimate row ${i} (${r[0]}) has an empty "How" cell`); });
    const rows = [...(p.tech || []), ...(p.tradeoffs || []), ...(p.scaling || []), ...(p.failures || []), ...(p.components || [])];
    rows.forEach(r => r.forEach(cell => { if (nWords(cell) > 32) F.push(`a table cell is ${nWords(cell)} words (max 32): "${prose(cell).slice(0, 40)}…"`); }));
    miniGraph(get(p, 'hld.diagram'), 'high-level diagram', F);
    common(p, ['entities.code', 'apis.code', 'v1.code'], F, W);
  },
  solution(s, F, W) {
    ['clarify', 'estimate', 'api', 'data', 'hld', 'deep', 'bottlenecks', 'tradeoffs'].forEach(k => { if (s[k] == null) F.push(`phase "${k}" is missing`); });
    if (get(s, 'clarify.ask.length') < 3) F.push('fewer than 3 clarifying questions');
    if (get(s, 'tradeoffs.followups.length') < 3) F.push('fewer than 3 follow-up questions');
    if (!(get(s, 'tradeoffs.traps') || []).length) F.push('no "mistakes candidates make" list');
    if ((s.deep || []).length < 2) F.push('fewer than 2 deep dives');
    const thinks = [['clarify', get(s, 'clarify.think')], ['estimate', get(s, 'estimate.think')], ['api', get(s, 'api.think')], ['data', get(s, 'data.think')], ['hld', get(s, 'hld.think')], ['bottlenecks', get(s, 'bottlenecks.think')], ['tradeoffs', get(s, 'tradeoffs.think')], ...(s.deep || []).map((d, i) => [`deep ${i}`, d.think])];
    thinks.forEach(([k, t]) => { if (!t) F.push(`"thinking out loud" missing in ${k}`); else if (nSent(t) > 5) F.push(`"thinking out loud" in ${k} has ${nSent(t)} sentences (max 5)`); });
    try { // the estimate must compute
      const E = s.estimate, v = {}, r = {}; E.inputs.forEach(([k, , d]) => { v[k] = d; }); E.rows.forEach(([k, , fn]) => { r[k] = fn(v, r); });
      Object.entries(r).forEach(([k, x]) => { if (typeof x !== 'number' || !isFinite(x)) F.push(`estimate row ${k} is not a number`); });
      const so = E.so(r, k => String(k in r ? r[k] : v[k]), v); if (/NaN|undefined/.test(so)) F.push('estimate "So what?" text has NaN or undefined');
    } catch (e) { F.push(`estimate does not compute: ${e.message}`); }
    miniGraph(get(s, 'hld.diagram'), 'high-level diagram', F);
    (s.deep || []).forEach((d, i) => { if (d.diagram) miniGraph(d.diagram, `deep dive ${i} diagram`, F); });
    common(s, ['api.code', 'data.code', 'code.src', 'code.title'], F, W);
  },
  scenario(s, F, W) {
    const ch = s.choices || [];
    if (ch.length !== 4) F.push(`${ch.length} first-move choices (need exactly 4)`);
    if (ch.filter(c => c[1] === 'best').length !== 1) F.push('need exactly one "best" first move');
    ch.forEach((c, i) => { if (!c[2] || nSent(c[2]) < 1) F.push(`choice ${i + 1} has no explanation`); });
    ['diagnose', 'options', 'decision', 'plan', 'risks', 'measure', 'say'].forEach(k => { if (!s.walk || !s.walk[k]) F.push(`walkthrough part "${k}" is missing`); });
    ((s.walk || {}).options || []).forEach((r, i) => { if (r.length !== 4) F.push(`options row ${i} needs 4 cells`); });
    ['title', 'context', 'drivers', 'options', 'decision', 'positive', 'negative', 'revisit'].forEach(k => { if (!s.adr || !s.adr[k]) F.push(`decision record field "${k}" is empty`); });
    if (!/<p>/.test(s.situation || '')) F.push('situation has no paragraph');
    else if (nSent(s.situation) > 8) F.push(`situation has ${nSent(s.situation)} sentences (max 8)`);
    if (s.before) miniGraph(s.before, 'diagram "before"', F);
    if (s.after) miniGraph(s.after, 'diagram "after"', F);
    common(s, [], F, W);
  },
};

/* ---------- ids must never change ---------- */
const idsFile = path.join(__dirname, 'content-ids.json');
const currentIds = Object.fromEntries(TYPES.map(t => [t, items[t].map(x => x.id).sort()]));
if (saveIds) { fs.writeFileSync(idsFile, JSON.stringify(currentIds, null, 1) + '\n'); console.log('saved', idsFile); process.exit(0); }
let savedIds = {}; try { savedIds = JSON.parse(fs.readFileSync(idsFile, 'utf8')); } catch (e) { /* no saved list yet */ }

/* ---------- run ---------- */
let failedTotal = 0, passTotal = 0;
console.log('Content check (Phase D)\n');
loadErrors.forEach(e => { console.log('ERROR ' + e); process.exitCode = 1; });
for (const t of TYPES) {
  if (only.length && !only.includes(t)) continue;
  const list = items[t]; let pass = 0; const lines = [];
  for (const it of list) {
    const F = [], W = []; try { CHECK[t](it, F, W); } catch (e) { F.push(`checker error: ${e.message}`); }
    if (F.length) { failedTotal++; lines.push(`  FAIL ${it.id}`); F.slice(0, verbose ? 99 : 3).forEach(f => lines.push(`       - ${f}`)); if (!verbose && F.length > 3) lines.push(`       … ${F.length - 3} more (use -v)`); }
    else { pass++; passTotal++; lines.push(`  PASS ${it.id}`); }
    if (verbose) W.slice(0, 5).forEach(w => lines.push(`       ~ ${w}`));
  }
  const missing = (savedIds[t] || []).filter(id => !currentIds[t].includes(id));
  console.log(`${t}: ${pass}/${list.length} items pass`);
  if (verbose || pass < list.length) lines.forEach(l => console.log(l)); else console.log('  all pass');
  missing.forEach(id => { console.log(`  FAIL id "${id}" is missing (ids must not change)`); failedTotal++; });
  console.log('');
}
console.log(`Total: ${passTotal} items pass, ${failedTotal} problems.`);
if (failedTotal) process.exitCode = 1;
